def compute(vars):
    value_2018 = vars["v1"]
    value_2019 = vars["v2"]

    if value_2018 == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "percent"}}}

    change = value_2019 - value_2018
    percentage_change = (change / value_2018) * 100

    return {
        "value": percentage_change,
        "trace": {
            "value_2018": value_2018,
            "value_2019": value_2019,
            "change": change,
            "output_meta": {"currency": None, "scale": None, "unit": "percent"}
        }
    }
